#include <iostream>
using namespace std;
int a[1005], dp[1005];
int main() {
    int n; cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    int ans = 0;
    for (int i = 1; i <= n; i++) {        // LIS 最长上升子序列
        dp[i] = 1;
        for (int j = 1; j < i; j++)
            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);
        ans = max(ans, dp[i]);
    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
using namespace std;
int g[105][105], n, m;   // 邻接矩阵
bool vis[105];
void dfs(int u) {        // 深度优先遍历
    vis[u] = true;
    cout << u << " ";
    for (int v = 1; v <= n; v++)
        if (g[u][v] && !vis[v]) dfs(v);
}

#include <iostream>
using namespace std;
int n, m;
char mp[105][105];
bool vis[105][105];
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};
void flood(int x, int y) {
    vis[x][y] = true;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= m
            && !vis[nx][ny] && mp[nx][ny] == '#')
            flood(nx, ny);   // 蔓延到下一格
    }
}

